def find_original_words(words, unique_ending):
    if len(words) == 1:
        return 1
    if len(words) == 2:
        return 2
    if len(words) == 3:
        return 4

    results = (catalan(len(words)-2) // len(words)) % MOD
    for word in unique_ending:
        result = (catalan(len(words)-3) * len(words)) % MOD
        for i in range(1, len(word)):
            result = (result + catalan(len(words)-3)*math.binomial(len(words)-1, i-1)) % MOD
        if word in unique_ending:
