        penalties = 0
        for i in order:
            if problems[i][3] >= 1:
                t -= problems[i][3]
                if problems[i][0] + math.exp(-problems[i][0] / problems[i][2]) < problems[i][1] + math.exp(-problems[i][1] / problems[i][2]):
                    points += problems[i][0] + math.exp(-problems[i][0] / problems[i][2])
                    penalties += problems[i][2] * math.exp(-problems[i][0] / problems[i][2])
                else:
                    points += problems[i][1]
                    penalties += problems[i][2] + math.exp(-problems[i][1] / problems[i][2])
            else:
                if not problems[i][2]:
                    penalties += t
                else:
                    t -= problems[i][2]

        return points, penalties

    total_points_best = 0
    best_penalty = float('inf')
    for perm in range(1, 1 << n):
