from heapq import heappush, heappop

def dijkstra(graph, start, end=None):
    distance = {city: float('inf') for city in range(1, n+1)}
    distance[start] = 0
    pq = [(0, start)]

    while pq:
        current_distance, current_city = heappop(pq)

        if current_city == end:
            return distance[end]

        if current_distance > distance[current_city]:
            continue

        for neighbor, weight in graph[current_city]:
            distance[neighbor] = min(distance[neighbor], current_distance + weight)
            heappush(pq, (current_distance + weight, neighbor))

    return distance[end] if end else float('inf')

