        return S // X

    # Recursive function to find the shortest length
    def shortest_length_recursive(X, S, N=1):
        if X <= S and S % X == 0:
            return S // X
        else:
            for i in range(1, N + 1):
                dim1 = X | (X << N)  # An element not in set A
                dim2 = (i << S // N)  # An element not in set B
                if dim1 & dim2 == 0:
                    return N + shortest_length_recursive(X, S - (S // N) * (i << (S // N)), i)
            return -1

    return shortest_length_recursive(X, S)

