from collections import defaultdict
from math import gcd
from functools import lru_cache

# Cache to memoize results
@lru_cache(maxsize=None)
def extended_gcd(a, b):
    if a < b:
        a, b = b, a
    if b == 0:
        return a, 1, 0
    d, x0, y0 = extended_gcd(b, a % b)
    x = x0 - (a // b) * y0
    y = y0
    return d, x, y

def find_gcd(a, b):
    """Extended GCD to find the Greatest Common Divisor."""
    d, x, _ = extended_gcd(b, a)
    return d

class FibonacciTree:
    def __init__(self):
        self.cache = {}

    def dfs(self, index, include_mod=False):
        if index in self.cache:
            return self.cache[index]
        n = 6 + index * 2
        self.cache[index] = (find_gcd(n // 2, index * 2) ** 2, super().dfs(index + 1) + super().dfs(index + 2))
        return self.cache[index]

    def core(self, remainder):
        if remainder in self.cache:
            return self.cache[remainder]
        limit = remainders.index(remainder)
        result, remainder = super().dfs(0, include_mod=True)
        res = {i * 765 + remainder for i, n in enumerate(range(2)) for _ in range(limit, n // 2)}
        self.cache[remainder] = result
        return res

class Solution:
    def modInverse(self, a, p):
        """Find modular inverse of a."""
        root, _ = ext_gcd(a, p)

        if root < 0:
            root += p

        return root

    @classmethod
    @lru_cache(None)
    def compute(cls, n):
        base = base_per_powers_below[1000000009 // n]
        cls.base_1000000009 = pow(base // n, pow(n, -1, 1000000009), 1000000009)

    def prefixsum(self, n, result):
        """Calculate the prefix sum of modulo 1000000003."""
        for i in range(n, n + 1):
            self.prime.multiply_and_put(i, result)

    def main(self, _input):
        n, m = map(int, _input)

        ans = [0] * n
        self.compute(n)
        remainder = n * n
        self.prefixsum(n, remainder)
        for _ in range(m):
            x, y = map(int, next(_input).split())
            target = find_gcd(remainder // y, y) ** 2
            ans[0] = (x - 1) * self.prime.pow(target * 2, -1, 1000000009) + pow(self.base_1000000009, -1, 1000000009)
            ans[0] %= 1000000003
        return ans

if __name__ == "__main__":
    assert Solution().main(["4", "3 2", "5 3"]) == [10, 1, 21, 14, 14, 11, 21, 11, 16]
