import math

def count_ways(words):
    mod = 10**9 + 7
    n = len(words)

    dp = [-math.inf] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        if len(words[i - 1]) < i:
            dp[i] = 0
        else:
            for j in range(min(i, len(words[i - 1])), -1, -1):
                if j == len(words[i - 1]):
                    dp[i] = (dp[i] + 1) % mod
                elif dp[j - 1] != -math.inf:
                    dp[i] = (dp[i] + dp[j - 1]) % mod
            dp[i] = (dp[i] + (-dp[i]) & int((mod - (i + 1)))) % mod

    return dp[-1]

