from bisect import insort
from collections import defaultdict

MOD = 10**9 + 7
MAX_WORD_LEN = 10**6 + 1

class Scroll:
    def __init__(self):
        self.cache = {0: 1}
        self.common_words = defaultdict(int)
        self.used_words = set()

    def add(self, word):
        for i in range(1, len(word) + 1):
            hash_key = self._get_hash_key(word[:i])
            insort(self.cache[hash_key], i - 1)

    def _get_hash_key(self, prefix):
        counter = max(self.common_words[prefix])
        return prefix, sum((w >> (counter - 1)) & 1 for w in self.used_words)

    def reset(self, word):
        for i in range(1, len(word) + 1):
            hash_key = self._get_hash_key(word[:i])
            pos = bisect.bisect_right(self.cache[hash_key], len(word) - i + 1) - 1
            self.cache[hash_key][pos] = len(word)
        self.common_words[word] -= 1
        if self.common_words[word] <= 0:
            del self.common_words[word]
        self.used_words -= set(word)

    def next_word(self, word):
        hash_key = self._get_hash_key(word)
        insort(self.cache[hash_key], len(word))
        new_words = set()
        for i in range(len(word)):
            neg_i = -i - 1
            pos = bisect.bisect_right(self.cache[hash_key], len(word) - i + 1)
            new_i = cmp(self.cache[hash_key][pos], len(word) - i + 1) - 1
            overflow = new_words - {t[len(word):] for t in new_words}
            delta = pos - new_i
            left = self.cache[hash_key][bisect.bisect_left(self.cache[hash_key], i - delta)] - 1
            val = self.common_words[word] << (neg_i + 1) | (self.cache[hash_key][pos] - left - val) - ((len(word) - i + 1) << (self.common_words[word] + neg_i + 1))
            if val in self.common_words:
                new_words |= set(w[len(word):] for w in self.common_words.pop(val))
            right = len(word) - i + 1 - self.common_words[word]
            if right > 0:
                overflow |= set(w[-(i - delta) - left - right] for w in new_words)
            new_words.add(word[:i] + str(new_i))
        self.common_words |= (new_words - set(word)).copy()
        if self.common_words[word] == 0:
            del self.common_words[word]
        self.used_words |= (set(word[1:]) - set(word)).copy()
        return " ".join(new_words)

def solve(tuple_):
    document = Scroll()
    original = sorted(tuple_[1:])
    drop_count = 0
    for word in tuple_[0].split():
        drop_count += (len(word) > 1)
        if word not in original:
            document.add(word)
    if document.cache[0]: return 0
    new_document = defaultdict(list)
    for w in sorted(tuple_[0].split(), key=len):
        for i in document.cache[document._get_hash_key(w)]:
            if i + len(w) < len(document.cache[0]):
                new_document[i + len(w)].append(w)
    ele = set(new_document[0]).difference(original + tuple_[1:])
    all_combinations = 1
    comb = []
    for i in range(len(document.cache[0]), len(document.cache)):
        ele = set(new_document[i]).difference(sorted(new_document[i], key=len), original + tuple_[1:])
        if not ele:
            break
        else:
            comb.append(sorted(ele))
    bit_sum = 1
    for i, drop in enumerate(drop_count):
        if i < len(comb):
            if len(comb[i]) > 1:
                bit_sum = (2 * bit_sum) % MOD
            for j in range(len(comb[i]) - 1):
                bit_sum = ((4 * bit_sum) % MOD - comb[i][j] * comb[i][j - 1] - modpow(2, drop) * N % MOD + 10**9 + 7) % MOD
    ans = 0
    for i in range(1, len(document.cache[0]) + 1):
        ans = (ans + bit_sum * comb[drop_count - i].count(i)) % MOD
    return ans

