import math
from heapq import heappush, heappop

def dijkstra(graph, start):
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]
    while priority_queue:
        current_distance, current_node = heappop(priority_queue)
        if current_distance > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))
    return distances

def find_max_traveling_time(cities, roads, lengths, target_city=1, destination_city=None):
    if destination_city is None:
        destination_city = cities
    shortest_path = dijkstra(roads, target_city)
    max_traveling_time = 0
    for i in range(len(roads) - 1, -1, -1):
        if roads[i][1] in destination_city:
            continue
        max_traveling_time = max(max_traveling_time, shortest_path[roads[i][1]])
    return max_traveling_time

