mod = 998244353

def powmod(a, b):
    result = 1
    a = a % mod
    while b:
        if b & 1:
            result = (result * a) % mod
        a = (a * a) % mod
        b >>= 1
    return result % mod

def solve(n, k, ans):
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(n):
        dp[i + 1] = (dp[i] + powmod(k, n)) % mod
        if i + 1 < n:
            dp[i + 1] = (dp[i + 1] + powmod(k, n - i - 1) * powmod(k - 1, i) % mod) % mod

    ans = powmod(ans, ans) % mod
    for i in range(n):
        ans = (ans * powmod(k, i) % mod) % mod
    return (dp[n] * ans) % mod

