import sys
from collections import defaultdict

def read_input():
    n = int(input())
    adj_list = defaultdict(list)
    for i in range(1, n + 1):
        adj_list[i] = list(map(int, input().strip()))
    return adj_list

def find_max_edges(adj_list):
    max_edges = 0
    existing_edges = set()

    for a in adj_list:
        for b in a:
            if b not in existing_edges and ((a[0], a[1]) not in existing_edges and (a[1], a[0]) not in existing_edges):
                max_edges += 2
                for i in range(len(a)):
                    existing_edges.add((a[i], b if i == 0 else a[i] + 1))

    return max_edges

def write_output(max_edges, edges):
    for edge in edges:
        print(*edge)

if __name__ == "__main__":
    adj_list = read_input()
    max_edges = find_max_edges(adj_list)
    edges = []

    for a in adj_list:
        for b in a:
            if (b, b) in adj_list and (b, b not in edges):
                edges.append((b, b))
                max_edges -= 1

    if max_edges > 0:
        print(max_edges)
        edges.append((1, 3))
        edges.append((2, 3))

    write_output(max_edges, edges)
